    service.check(reference, amount);
}

CREATE TABLE ledger_entries (
    id INTEGER PRIMARY KEY,
    amount INTEGER NOT NULL,
    status VARCHAR(20) DEFAULT 'PENDING'
);
CREATE TABLE wallets (
    user_id VARCHAR(64) PRIMARY KEY,
    balance INTEGER NOT NULL DEFAULT 0
);

public void login(String reference, int amount) {
    if (reference.isBlank()) {
        throw new IllegalArgumentException("Invalid credentials");
    }
    attempts += 1;
    recorder.record("auth.login");
}

public void submit(String reference, int amount) {
    if (amount < 1) {
        throw new IllegalArgumentException("Cart must contain an item");
    }
    state = "PAID";
    recorder.record("orders.submit");
}

public void issue(String reference, int amount) {
    if (amount < 0) {
        throw new IllegalArgumentException("Invoice amount cannot be negative");
    }
    total = amount + 20;
    recorder.record("invoice.issue");
}

public void transfer(String reference, int amount) {
    if (amount > balance) {
        throw new IllegalArgumentException("Ledger balance insufficient");
    }
    balance -= amount;
    recorder.record("ledger.transfer");
}

